import {createHash} from 'node:crypto';
const root='D:/Projects/hmem';
const scratch=`${root}/.scratch/sealed-archives-5e25a6ed`;
const cases=[['small',2097169,1021,'jsonl'],['empty',0,65536,'jsonl'],['one',1,1,'jsonl'],['oneMiB',1048576,65536,'jsonl'],['hundredMiB',104857600,65536,'jsonl'],['oneGiB',1073741824,65536,'jsonl'],['randomMiB',1048576,1021,'random'],['random100MiB',104857600,65536,'random']];
