for(const [label,size,chunk,kind] of cases){
  const args=[String(size),String(chunk),kind,`${scratch}/${label}`];
  const result=spawnSync(`${scratch}/codec_probe.exe`,args,{cwd:root,encoding:'utf8',timeout:120000,maxBuffer:65536,windowsHide:true});
